```javascript
function createOrchestrator() {
  const handlers = new Map();
  let stats = { total: 0, successes: 0, failures: 0 };
  return {
    register(name, fn) { handlers.set(name, fn); },
    execute(name, payload, fallback) {
      stats.total++;
      const fn = handlers.get(name);
      if (!fn) {
        stats.failures++;
        return { success: false, result: null, error: `Handler not found: ${name}` };
      }
      try {
        const res = fn(payload);
        stats.successes++;
        return { success: true, result: res, error: null };
      } catch (err) {
        if (typeof fallback === 'function') {
          try {
            const fbRes = fallback(payload);
            stats.successes++;
            return { success: true, result: fbRes, error: err.message, recovered: true };
          } catch (fbErr) {
            stats.failures++;
            return { success: false, result: null, error: fbErr.message };
          }
        }
        stats.failures++;
        return { success: false, result: null, error: err.message };
      }
    },
    getStats() { return { ...stats }; }
  };
}
```

